{
  "outcome": "escalate",
  "rationale": "We must escalate this claim because automated findings indicate it is unclear whether an exclusion applies due to disputed facts regarding how the collision occurred. This decision is governed by section BASIC-6.2 which mandates escalation when material facts are open to more than one reasonable reading.",
  "citations": [
    {
      "clause_id": "BASIC-6.2",
      "quote": "If the documents submitted do not allow the adjuster to determine whether an exclusion applies, because material facts are disputed, missing or open to more than one reasonable reading, the claim must be escalated for further investigation rather than approved or denied on the information available."
    }
  ]
}
